components.variantCss:
#wemd .wemd-hero-banner[data-variant="hero-banner-brand-featured"] {
  background: linear-gradient(135deg, #2563EB, rgb(0,59,195));
  color: #fff;
  padding: 2.5em 1.5em;
  border-radius: 12px;
  text-align: center;
}
#wemd .wemd-hero-banner[data-variant="hero-banner-brand-featured"] .wemd-hero-title {
  font-size: 1.75em;
  font-weight: 700;
  margin: 0 0 0.5em;
  color: #fff;
}
#wemd .wemd-hero-banner[data-variant="hero-banner-brand-featured"] .wemd-hero-subtitle {
  font-size: 1em;
  opacity: 0.9;
  color: rgba(255,255,255,0.9);
}

#wemd .wemd-stats-block[data-variant="stats-block-brand-default"] {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1em;
  padding: 1.5em;
  background: #F8FAFC;
  border-radius: 10px;
  border: 1px solid #E2E8F0;
}
#wemd .wemd-stats-block[data-variant="stats-block-brand-default"] .wemd-stat-value {
  font-size: 1.5em;
  font-weight: 700;
  color: #2563EB;
}
#wemd .wemd-stats-block[data-variant="stats-block-brand-default"] .wemd-stat-label {
  font-size: 0.85em;
  color: #64748B;
}

#wemd .wemd-code-block[data-variant="code-block-brand-default"] {
  background: #1E293B;
  color: #E2E8F0;
  border-radius: 8px;
  padding: 1.25em;
  font-family: "JetBrains Mono", "Fira Code", monospace;
  font-size: 0.85em;
  overflow-x: auto;
  margin: 1.25em 0;
}

#wemd .wemd-callout[data-variant="callout-brand-default"] {
  border-left: 4px solid #2563EB;
  background: #F8FAFC;
  padding: 1em 1.25em;
  border-radius: 0 8px 8px 0;
  margin: 1.25em 0;
}
#wemd .wemd-callout[data-variant="callout-brand-default"] .wemd-callout-title {
  font-weight: 600;
  color: #2563EB;
  margin-bottom: 0.25em;
}
#wemd .wemd-callout[data-variant="callout-brand-default"] .wemd-callout-content {
  color: #1A1A2E;
  font-size: 0.95em;
}
